/*
 * A069694  Triangular numbers with internal digits 2.
 * https://oeis.org/A069694
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  fini, full, nonn, base
 * Formula:   a(n) = nth triangular number whose internal (non‑leading,
 *            non‑trailing) decimal digits are all 2. The sequence is finite;
 *            it is generated by scanning triangular numbers up to a preset
 *            limit
 * Range:     u8 n <= 6, u16 n <= 19, u32 n <= 19, u64 n <= 19, u128 n <= 19,
 *            big any n
 * Helpers:   internal_digits_two
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include "../utils/internal_digits_two.h"

/* Cache for the finite set of qualifying triangular numbers. */
static seq_t cache[200];
static size_t cache_cnt = 0;
static bool cache_built = false;

/* Build the cache once.  The limit is chosen large enough to include all known terms
   (currently 1225).  No terms above 10000 exist. */
static void build_cache(void)
{
    if (cache_built) return;
    cache_built = true;

    /* Upper bound for triangular numbers we scan. */
    const seq_t max_limit = (seq_t)10000;

    idx_t k = 0;
    while (1) {
        seq_t t = ((seq_t)k * ((seq_t)k + (seq_t)1)) / (seq_t)2;
        if (t > max_limit) break;

        if (internal_digits_two(t)) {
            cache[cache_cnt++] = t;
        }
        ++k;
    }
}

/* Sequence entry.  Returns 0 for indices beyond the finite list. */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* guard against zero; offset is 1 */

    build_cache();

    if ((idx_t)(n - 1) < cache_cnt) {
        return cache[n - 1];
    }
    return 0; /* finite sequence – no further terms */
}
